import sys
from itertools import product

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    k = int(input_data[0])
    m = int(input_data[1])

    results = []

    for digits in product(range(10), repeat=8):
        s = ''.join(map(str, digits))

        nums = []
        current = 0
        for d in digits:
            current = current * 10 + d
            nums.append(current)

        if len(nums) == 1:
            if nums[0] == k:
                results.append(s)
        else:
            dp = {nums[0]}
            for i in range(1, len(nums)):
                new_dp = set()
                for val in dp:
                    new_dp.add(val + nums[i])
                    new_dp.add(val - nums[i])
                    new_dp.add(val * nums[i])
                dp = new_dp

            if k in dp:
                results.append(s)

        if len(results) >= m:
            break

    for r in results[:m]:
        print(r)

if __name__ == "__main__":
    solve()
